json TagMetaDto::toJson() const {
  json tagMeta = {};
  tagMeta["tagName"] = tagName;
  tagMeta["description"] = description;
  tagMeta["tagInfo"] = tagInfo;
  if (insertionTime.has_value())
    tagMeta["insertionTime"] = insertionTime.value();
  return tagMeta;
}

