TagMetaDto TagMetaDto::fromJson(const json &j) {
  TagMetaDto tag;
  tag.tagName = StringUtils::getStringOr(j, "tagName");
  tag.tagInfo = StringUtils::getStringOr(j, "tagInfo");
  tag.description = StringUtils::getStringOr(j, "description");
  if (j.contains(std::string{"insertionTime"}))
    tag.insertionTime = j.value("insertionTime", "");
  return tag;
}

